INSERT INTO `ddmtemplate` VALUES (0,0,'283279eb-da4a-ddeb-deb4-f0329a5bd3cf','283279eb-da4a-ddeb-deb4-f0329a5bd3cf',31231,20120,39084709973119,20096,NULL,20096,NULL,'2026-02-23 13:09:11.886000','2026-02-23 13:09:11.886000',29221,31227,29257,'BASIC-WEB-CONTENT','1.0','<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Name language-id=\"sv_SE\">Vanligt innehåll</Name><Name language-id=\"pt_BR\">Conteúdo Web básico</Name><Name language-id=\"ja_JP\">基本Webコンテンツ</Name><Name language-id=\"fr_FR\">Contenu web basique</Name><Name language-id=\"hu_HU\">Alapvető webtartalom</Name><Name language-id=\"de_DE\">Einfacher Webcontent</Name><Name language-id=\"ca_ES\">Contigut web bàsic</Name><Name language-id=\"ar_SA\">تحرير محتوى</Name><Name language-id=\"fi_FI\">Tavallinen web-sisältö</Name><Name language-id=\"en_US\">Basic Web Content</Name><Name language-id=\"zh_CN\">基本 Web 内容</Name><Name language-id=\"es_ES\">Contenido web básico</Name><Name language-id=\"nl_NL\">Basiswebcontent</Name></root>','','display','create','ftl','${content.getData()}',1,0,31233,NULL,NULL),(0,0,'ccdf2028-343a-e1a9-59f6-5debeb2370e5','ccdf2028-343a-e1a9-59f6-5debeb2370e5',33179,20120,39084709973119,20096,NULL,20096,NULL,'2026-02-23 13:16:15.175000','2026-02-23 13:16:15.175000',33177,0,33178,'BREADCRUMB-ARROWS-FTL','1.0','<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Name language-id=\"sv_SE\">Pilar</Name><Name language-id=\"pt_BR\">Setas</Name><Name language-id=\"ja_JP\">矢印</Name><Name language-id=\"fr_FR\">Flèches</Name><Name language-id=\"hu_HU\">Nyilak</Name><Name language-id=\"de_DE\">Pfeile</Name><Name language-id=\"ca_ES\">Fletxes</Name><Name language-id=\"ar_SA\">الأسهم</Name><Name language-id=\"fi_FI\">Nuolet</Name><Name language-id=\"en_US\">Arrows</Name><Name language-id=\"zh_CN\">箭头</Name><Name language-id=\"es_ES\">Flechas</Name><Name language-id=\"nl_NL\">Pijlen</Name></root>','<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Description language-id=\"sv_SE\">Visar en länkstig där varje navigeringselement representeras av en pil med titel och länk.</Description><Description language-id=\"pt_BR\">Exibe um caminho de navegação onde cada elemento de navegação é representado por uma seta com seu título e link.</Description><Description language-id=\"ja_JP\">すべてのナビゲーション要素が矢印とタイトル、リンクで表示されるように、パンくずリストを表示します。</Description><Description language-id=\"fr_FR\">Affiche un fil d\'Ariane dans lequel chaque élément de navigation est représenté par une flèche avec son propre titre et son propre lien.</Description><Description language-id=\"hu_HU\">Megjelenít egy úrkövetőt, amelyen minden navigációs elemet egy nyíl képvisel címmel és hivatkozással tartalmaz.</Description><Description language-id=\"de_DE\">Zeigt eine Breadcrumbnavigation an, bei der jedes Navigationselement durch einen Pfeil mit seinem Titel und einem Link dargestellt wird.</Description><Description language-id=\"ca_ES\">Mostra una ruta de navegació en què cada element de navegació es representa amb una fletxa amb el seu títol i enllaç.</Description><Description language-id=\"ar_SA\">يعرض مسار تنقل تفصيلي يتم فيه تمثيل كل عنصر تنقل بواسطة سهم به عنوانه ورابطه.</Description><Description language-id=\"fi_FI\">Näyttää murupolun, jossa jokainen navigointielementti näkyy nuolena otsikkoineen ja linkkinä.</Description><Description language-id=\"en_US\">Displays a breadcrumb in which every navigation element is represented by an arrow with its title and link.</Description><Description language-id=\"zh_CN\">显示一个面包屑导航，其中每一个导航元素都由箭头及其标题和链接表示。</Description><Description language-id=\"es_ES\">Muestra una ruta de navegación donde cada elemento de navegación se representa mediante una flecha con su título y enlace.</Description><Description language-id=\"nl_NL\">Geeft een broodkruimel weer waarin elk navigatie-element voorgesteld wordt door een pijl met een titel en link.</Description></root>','display',NULL,'ftl','<#if entries?has_content>\n	<@liferay_util[\"html-top\"]>\n		<style ${nonceAttribute}>\n			.breadcrumb-arrows li {\n				background-color: #EFEFEF;\n				margin-bottom: 3px;\n				overflow: visible;\n			}\n\n			.breadcrumb-arrows li + li::before {\n				content: none;\n			}\n\n			.breadcrumb-arrows li > a {\n				border-right: 4px solid #FFF;\n				display: block;\n				max-width: 100%;\n				position: relative;\n			}\n\n			.breadcrumb-arrows .entry {\n				line-height: 40px;\n				overflow: hidden;\n				padding-left: 30px;\n				padding-right: 7px;\n				text-overflow: ellipsis;\n				white-space: nowrap;\n			}\n\n			.breadcrumb-arrows a::after {\n				border-bottom: 20px inset transparent;\n				border-left: 20px solid #EFEFEF;\n				border-top: 20px inset transparent;\n				content: \'\';\n				height: 0;\n				position: absolute;\n				right: -20px;\n				top: 0;\n				width: 0;\n				z-index: 2;\n			}\n\n			.breadcrumb-arrows li:nth-child(n+2) a::before {\n				border-bottom: 20px inset transparent;\n				border-left: 20px solid #FFF;\n				border-top: 20px inset transparent;\n				content: \'\';\n				height: 0;\n				left: 0;\n				position: absolute;\n				top: 0;\n				width: 0;\n			}\n\n			.breadcrumb-arrows li:last-child {\n				border-bottom-right-radius: 4px;\n				border-right-width: 0;\n				border-top-right-radius: 4px;\n				position: relative;\n			}\n\n			.breadcrumb-arrows li:last-child::before {\n				border-bottom: 20px inset transparent;\n				border-left: 20px solid #FFF;\n				border-top: 20px inset transparent;\n				content: \'\';\n				height: 0;\n				left: 0;\n				position: absolute;\n				top: 0;\n				width: 0;\n			}\n\n			.breadcrumb-arrows li:last-child .entry {\n				padding-right: 23px;\n			}\n\n			.breadcrumb-arrows li:first-child {\n				border-bottom-left-radius: 4px;\n				border-top-left-radius: 4px;\n			}\n\n			.breadcrumb-arrows li:first-child::before {\n				border-left-width: 0;\n			}\n\n			.breadcrumb-arrows li:first-child .entry {\n				padding-left: 23px;\n			}\n\n			.breadcrumb-arrows .active {\n				background-color: #007ACC;\n			}\n\n			.breadcrumb-arrows .active a, .breadcrumb-arrows .active .entry {\n				color: #FFF;\n			}\n\n			.breadcrumb-arrows .active a::after {\n				border-left-color: #007ACC;\n			}\n\n			.portlet-barebone .breadcrumb-arrows li > a, .portlet-borderless .breadcrumb-arrows li > a, .taglib-portlet-preview .breadcrumb-arrows li > a {\n				border-right-color: #F5F7F8;\n			}\n\n			.portlet-barebone .breadcrumb-arrows li:last-child::before, .portlet-barebone .breadcrumb-arrows li:nth-child(n+2) a::before, .portlet-borderless .breadcrumb-arrows li:last-child::before, .portlet-borderless .breadcrumb-arrows li:nth-child(n+2) a::before, .taglib-portlet-preview .breadcrumb-arrows li:last-child::before, .taglib-portlet-preview .breadcrumb-arrows li:nth-child(n+2) a::before {\n				border-left-color: #F5F7F8;\n			}\n		</style>\n	</@>\n\n	<div class=\"breadcrumb breadcrumb-arrows\">\n		<#assign cssClass = \"\" />\n\n		<#list entries as entry>\n			<#if entry?is_last>\n				<#assign cssClass = \"active\" />\n			</#if>\n\n			<li class=\"${cssClass}\" <#if entry?is_last>aria-current=\"page\"</#if>>\n				<#if entry?has_next>\n					<a\n\n					<#if entry.isBrowsable()>\n						href=\"${entry.getURL()!\"\"}\"\n					</#if>\n\n					>\n				</#if>\n\n				<div class=\"entry\">\n					${htmlUtil.escape(entry.getTitle())}\n				</div>\n\n				<#if entry?has_next>\n					</a>\n				</#if>\n			</li>\n		</#list>\n	</div>\n</#if>',0,0,33180,NULL,NULL),(0,0,'4504107b-9327-45ff-c5e3-7898080d2b17','4504107b-9327-45ff-c5e3-7898080d2b17',33182,20120,39084709973119,20096,NULL,20096,NULL,'2026-02-23 13:16:15.196000','2026-02-23 13:16:15.196000',33177,0,33178,'BREADCRUMB-HORIZONTAL-FTL','1.0','<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Name language-id=\"sv_SE\">Horisontell</Name><Name language-id=\"pt_BR\">Horizontal</Name><Name language-id=\"ja_JP\">水平方向</Name><Name language-id=\"fr_FR\">Horizontal(e)</Name><Name language-id=\"hu_HU\">Vízszintes</Name><Name language-id=\"de_DE\">Horizontal</Name><Name language-id=\"ca_ES\">Horitzontal</Name><Name language-id=\"ar_SA\">أفقي</Name><Name language-id=\"fi_FI\">Vaakasuuntainen</Name><Name language-id=\"en_US\">Horizontal</Name><Name language-id=\"zh_CN\">水平</Name><Name language-id=\"es_ES\">Horizontal</Name><Name language-id=\"nl_NL\">Horizontaal</Name></root>','<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Description language-id=\"sv_SE\">Visar en länkstig horisontellt.</Description><Description language-id=\"pt_BR\">Exibe um caminho de navegação horizontalmente.</Description><Description language-id=\"ja_JP\">パンくずリストをを水平方向に表示します</Description><Description language-id=\"fr_FR\">Affiche un fil d\'Ariane de manière horizontale.</Description><Description language-id=\"hu_HU\">Megjelenít egy útkövetőjelet vízszintesen.</Description><Description language-id=\"de_DE\">Zeigt eine Breadcrumbnavigation horizontal an.</Description><Description language-id=\"ca_ES\">Mostra una ruta de navegació horitzontalment.</Description><Description language-id=\"ar_SA\">يعرض مسار تنقل أفقيًا.</Description><Description language-id=\"fi_FI\">Näyttää murupolun vaakasuoraan.</Description><Description language-id=\"en_US\">Displays a breadcrumb horizontally.</Description><Description language-id=\"zh_CN\">水平显示面包屑导航。</Description><Description language-id=\"es_ES\">Muestra una ruta de navegación horizontalmente.</Description><Description language-id=\"nl_NL\">Geeft een broodkruimel horizontaal weer.</Description></root>','display',NULL,'ftl','<#if entries?has_content>\n	<ol class=\"breadcrumb\">\n		<#list entries as entry>\n			<li class=\"breadcrumb-item\">\n				<#if entry?has_next>\n					<a\n						class=\"breadcrumb-link\"\n\n						<#if entry.isBrowsable()>\n							href=\"${htmlUtil.escapeAttribute(entry.getURL()!\"\")}\"\n						</#if>\n					>\n						<span class=\"breadcrumb-text-truncate\">${htmlUtil.escape(entry.getTitle())}</span>\n					</a>\n				<#else>\n					<span aria-current=\"page\" class=\"active breadcrumb-text-truncate\">${htmlUtil.escape(entry.getTitle())}</span>\n				</#if>\n			</li>\n		</#list>\n	</ol>\n</#if>',0,0,33183,NULL,NULL),(0,0,'1db0ba34-a735-776d-cfba-8271a1bc3843','1db0ba34-a735-776d-cfba-8271a1bc3843',33185,20120,39084709973119,20096,NULL,20096,NULL,'2026-02-23 13:16:15.204000','2026-02-23 13:16:15.204000',33177,0,33178,'BREADCRUMB-VERTICAL-FTL','1.0','<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Name language-id=\"sv_SE\">Vertikal</Name><Name language-id=\"pt_BR\">Vertical</Name><Name language-id=\"ja_JP\">垂直方向</Name><Name language-id=\"fr_FR\">Vertical</Name><Name language-id=\"hu_HU\">Függőleges</Name><Name language-id=\"de_DE\">Vertikal</Name><Name language-id=\"ca_ES\">Vertical</Name><Name language-id=\"ar_SA\">رأسي</Name><Name language-id=\"fi_FI\">Pystysuora</Name><Name language-id=\"en_US\">Vertical</Name><Name language-id=\"zh_CN\">垂直</Name><Name language-id=\"es_ES\">Vertical</Name><Name language-id=\"nl_NL\">Verticaal</Name></root>','<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Description language-id=\"sv_SE\">Visar en länkstig vertikalt.</Description><Description language-id=\"pt_BR\">Exibe um caminho de navegação verticalmente.</Description><Description language-id=\"ja_JP\">パンくずリストをを垂直方向に表示します</Description><Description language-id=\"fr_FR\">Affiche un fil d\'Ariane vertical.</Description><Description language-id=\"hu_HU\">Megjelenít egy útkövetőjelet függőlegesen.</Description><Description language-id=\"de_DE\">Zeigt eine Breadcrumbnavigation vertikal an.</Description><Description language-id=\"ca_ES\">Mostra una ruta de navegació verticalment.</Description><Description language-id=\"ar_SA\">يعرض مسار تنقل رأسيًا.</Description><Description language-id=\"fi_FI\">Näyttää murupolun pystysuoraan.</Description><Description language-id=\"en_US\">Displays a breadcrumb vertically.</Description><Description language-id=\"zh_CN\">垂直显示面包屑导航。</Description><Description language-id=\"es_ES\">Muestra una ruta de navegación verticalmente.</Description><Description language-id=\"nl_NL\">Geeft een broodkruimel verticaal weer.</Description></root>','display',NULL,'ftl','<#if entries?has_content>\n	<ul class=\"breadcrumb breadcrumb-vertical\">\n		<#assign cssClass = \"\" />\n\n		<#list entries as entry>\n			<#if entry?is_last>\n				<#assign cssClass = \"active\" />\n			</#if>\n\n			<li class=\"${cssClass}\" <#if entry?is_last>aria-current=\"page\"</#if>>\n				<#if entry?has_next>\n					<a\n\n					<#if entry.isBrowsable()>\n						href=\"${entry.getURL()!\"\"}\"\n					</#if>\n\n					>\n				</#if>\n\n				${htmlUtil.escape(entry.getTitle())}\n\n				<#if entry?has_next>\n					</a>\n				</#if>\n			</li>\n		</#list>\n	</ul>\n</#if>',0,0,33186,NULL,NULL),(0,0,'9edb35e3-6958-0b27-4db0-c838962edb23','9edb35e3-6958-0b27-4db0-c838962edb23',33189,20120,39084709973119,20096,NULL,20096,NULL,'2026-02-23 13:16:16.318000','2026-02-23 13:16:16.318000',33188,0,33178,'COMMERCE-ADDRESS-BASIC-FTL','1.0','<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Name language-id=\"sv_SE\">Standard</Name><Name language-id=\"pt_BR\">Básico</Name><Name language-id=\"ja_JP\">通常の検索に戻る</Name><Name language-id=\"fr_FR\">Basique</Name><Name language-id=\"hu_HU\">Egyszerű</Name><Name language-id=\"de_DE\">Einfach</Name><Name language-id=\"ca_ES\">Bàsic</Name><Name language-id=\"ar_SA\">أساسي</Name><Name language-id=\"fi_FI\">Perus</Name><Name language-id=\"en_US\">Basic</Name><Name language-id=\"zh_CN\">基本的</Name><Name language-id=\"es_ES\">Básico</Name><Name language-id=\"nl_NL\">Basis</Name></root>','<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Description language-id=\"sv_SE\">Visa rubriker, författare och sammanfattningar kompakt för blogginlägg.</Description><Description language-id=\"pt_BR\">Exibe títulos, autores e resumos compactamente para posts de blog.</Description><Description language-id=\"ja_JP\">タイトル、作成者、要約は、ブログエントリー用に小さくまとめられます</Description><Description language-id=\"fr_FR\">Affiche titres, auteurs, et abstraits de manière compacte pour les entrées de blog.</Description><Description language-id=\"hu_HU\">Megjeleníti kompakt módon a címeket, szerzőket és kivonatokat a blog bejegyzésekhez.</Description><Description language-id=\"de_DE\">Kompakte Darstellung von Titel, Autoren und Kurzfassungen für Blogeinträge.</Description><Description language-id=\"ca_ES\">Mostra els titles, autors i resums de forma compacta per les entrades del blog.</Description><Description language-id=\"ar_SA\">يعرض العناوين والمؤلفين والملخصات لإدخالات المدونات بشكل مضغوط.</Description><Description language-id=\"fi_FI\">Näyttää blogien otsikot, tekijät ja lyhenteet lyhyesti</Description><Description language-id=\"en_US\">Displays titles, authors, and abstracts compactly for blog entries.</Description><Description language-id=\"zh_CN\">简介显示博客的名字，作者和摘要。</Description><Description language-id=\"es_ES\">Muestra de forma compacta títulos, autores y resúmenes para las entradas del blog.</Description><Description language-id=\"nl_NL\">Geeft titels, auteurs en samenvatting compact weer voor blogs.</Description></root>','display',NULL,'ftl','<#assign count = 0 />\n\n<div class=\"container-fluid container-fluid-max-xl\" style=\"text-align:center\">\n	<div class=\"row\" style=\"padding:15px\">\n		<#if entries?has_content>\n			<#list entries as curCommerceAddress>\n				<div class=\"col-md-4\" style=\"text-align:left\">\n					<#assign\n						editURL = commerceAddressDisplayContext.getEditCommerceAddressURL(curCommerceAddress.getCommerceAddressId())\n\n						deleteURL = commerceAddressDisplayContext.getDeleteCommerceAddressURL(curCommerceAddress.getCommerceAddressId())\n\n						editButtonValue = languageUtil.get(request, \"edit\")\n\n						removeButtonValue = languageUtil.get(request, \"remove\")\n\n						commerceCountry = curCommerceAddress.getCommerceCountry()\n					/>\n\n					<h2 style=\"color:#000\"><strong>${htmlUtil.escape(curCommerceAddress.getName())}</strong></h2>\n\n					<h3 style=\"color:#000\">${htmlUtil.escape(curCommerceAddress.getStreet1())}</h3>\n\n					<h3 style=\"color:#000\">${htmlUtil.escape(curCommerceAddress.getZip())}, ${htmlUtil.escape(curCommerceAddress.getCity())}</h3>\n\n					<#if commerceCountry??>\n						<h3 style=\"color:#000\">${htmlUtil.escape(commerceCountry.getName(themeDisplay.getLanguageId()))}</h3>\n					</#if>\n\n					<div class=\"row\" style=\"padding-top:30px\">\n						<@liferay_aui.button\n							cssClass=\"btn-lg\"\n							href=\"${editURL}\"\n							name=\"editAddressButton\"\n							value=\"${editButtonValue}\"\n						/>\n\n						<@liferay_aui.button\n							cssClass=\"btn-lg\"\n							href=\"${deleteURL}\"\n							name=\"removeAddressButton\"\n							value=\"${removeButtonValue}\"\n						/>\n					</div>\n				</div>\n\n				<#assign count = count + 1 />\n\n				<#if count gte 3>\n					</div>\n\n					<div class=\"row\" style=\"padding:15px\">\n\n					<#assign count = 0 />\n				</#if>\n			</#list>\n		</#if>\n	</div>\n\n	<div class=\"row\" style=\"padding:50px 0 15px 0\">\n		<#assign addButtonValue = languageUtil.get(request, \"add-address\") />\n\n		<@liferay_aui.button\n			cssClass=\"btn-lg btn-primary\"\n			href=\"${commerceAddressDisplayContext.getAddCommerceAddressURL()}\"\n			name=\"addAddressButton\"\n			value=\"${addButtonValue}\"\n		/>\n	</div>\n</div>',0,0,33190,NULL,NULL),(0,0,'7b255125-53de-d6ff-82d8-f17ebe42d445','7b255125-53de-d6ff-82d8-f17ebe42d445',33192,20120,39084709973119,20096,NULL,20096,NULL,'2026-02-23 13:16:16.697000','2026-02-23 13:16:16.697000',20036,0,33178,'SITE-MAP-MULTI-COLUMN-LAYOUT-FTL','1.0','<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Name language-id=\"sv_SE\">Layout med flera kolumner</Name><Name language-id=\"pt_BR\">Layout em Múltiplas Colunas</Name><Name language-id=\"ja_JP\">複数カラムレイアウト</Name><Name language-id=\"fr_FR\">Mise en page multi-colonne</Name><Name language-id=\"hu_HU\">Több oszlopos elrendezés</Name><Name language-id=\"de_DE\">Multi-Spalten-Layout</Name><Name language-id=\"ca_ES\">Plana multi-columna</Name><Name language-id=\"ar_SA\">تخطيط أعمدة متعددة</Name><Name language-id=\"fi_FI\">Usean sarakkeen asettelu</Name><Name language-id=\"en_US\">Multi Column Layout</Name><Name language-id=\"zh_CN\">多列布局</Name><Name language-id=\"es_ES\">Diseño con varias columnas</Name><Name language-id=\"nl_NL\">Lay-out met meerdere kolommen</Name></root>','<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Description language-id=\"sv_SE\">Visar en kolumn för varje sida på den högsta nivån. Varje kolumn inkluderar namnet på varje sida på den högsta nivån samt sidans omedelbara underordnade element listade under den.</Description><Description language-id=\"pt_BR\">Exibe uma coluna para cada página de nível superior. Cada coluna inclui o nome de uma página de nível superior com os filhos imediatos da página listados abaixo.</Description><Description language-id=\"ja_JP\">最上位のページごとに列を表示します。各列には、トップレベルのページの名前と、直下のサブページのページ名を含みます。</Description><Description language-id=\"fr_FR\">Affiche une colonne pour chaque page de niveau supérieur. Chaque colonne comprend le nom d\'une page de niveau supérieur avec les enfants immédiats indiqués en-dessous.</Description><Description language-id=\"hu_HU\">Megjelenít egy oszlopot minden felső szintű oldalhoz. Mindegyik oszlop tartalmazza a legfelső szintű oldal nevét, alatta az oldal közvetlen utódjával.</Description><Description language-id=\"de_DE\">Zeigt eine Spalte für jede Seite der obersten Ebene. Jede Spalte enthält den Namen einer Seite der obersten Ebene, darunter werden die direkten Unterseiten aufgelistet.</Description><Description language-id=\"ca_ES\">Mostra una columna per cada pàgina de nivell superior. A cada columna, s\'hi inclou el nom d\'una pàgina de nivell superior amb el fill immediat de la pàgina en una llista a la part inferior.</Description><Description language-id=\"ar_SA\">يعرض عمودًا لكل صفحة مستوى أعلى. يتضمن كل عمود اسم صفحة المستوى العلوي بفروع متوسطة للصفحة مدرجة أسفلها.</Description><Description language-id=\"fi_FI\">Näyttää sarakkeen jokaiselle ylätason sivulle. Jokainen sarake sisältää ylätason sivun nimen ja sivun välittömät alasivut lueteltuna alapuolella.</Description><Description language-id=\"en_US\">Displays a column for each top level page. Each column includes the name of a top level page with the page\'s immediate children listed underneath.</Description><Description language-id=\"zh_CN\">为每个顶级页面显示一列。每一列都包含顶级页面的名称以及页面下所列的直接子级。</Description><Description language-id=\"es_ES\">Muestra una columna por cada página de nivel superior. En cada columna, se incluye el nombre de una página de nivel superior con el elemento secundario inmediato de la página en una lista de la parte inferior.</Description><Description language-id=\"nl_NL\">Geeft een kolom weer voor elke pagina op het hoogste niveau. Elke kolom bevat de naam van een bovenliggende pagina met alle directe onderliggende pagina\'s eronder.</Description></root>','display',NULL,'ftl','<#if entries?has_content>\n	<@clay.row>\n		<#list entries as entry>\n			<#if (getterUtil.getBoolean(showHiddenPages) || !entry.isHidden()) && layoutPermission.containsWithoutViewableGroup(permissionChecker, entry, \"VIEW\")>\n				<@clay.col md=\"3\">\n					<div class=\"results-header\">\n						<h3>\n							<a\n\n							<#assign layoutType = entry.getLayoutType() />\n\n							<#if layoutType.isBrowsable()>\n								href=\"${portalUtil.getLayoutURL(entry, themeDisplay)}\"\n							</#if>\n\n							>${entry.getName(locale)}</a>\n						</h3>\n					</div>\n\n					<@displayPages\n						depth = 1\n						pages = entry.getChildren(permissionChecker)\n					/>\n				</@clay.col>\n			</#if>\n		</#list>\n	</@clay.row>\n</#if>\n\n<#macro displayPages\n	depth\n	pages\n>\n	<#if pages?has_content && ((depth < displayDepth?number) || (displayDepth?number == 0))>\n		<ul class=\"child-pages\">\n			<#list pages as page>\n				<#if getterUtil.getBoolean(showHiddenPages) || !page.isHidden()>\n					<li>\n						<a\n\n						<#assign pageType = page.getLayoutType() />\n\n						<#if pageType.isBrowsable()>\n							href=\"${portalUtil.getLayoutURL(page, themeDisplay)}\"\n						</#if>\n\n						>${page.getName(locale)}</a>\n\n						<@displayPages\n							depth = depth + 1\n							pages = page.getChildren(permissionChecker)\n						/>\n					</li>\n				</#if>\n			</#list>\n		</ul>\n	</#if>\n</#macro>',0,0,33193,NULL,NULL),(0,0,'1c707820-4d4f-e07f-4545-8d4776a5839f','1c707820-4d4f-e07f-4545-8d4776a5839f',33195,20120,39084709973119,20096,NULL,20096,NULL,'2026-02-23 13:16:17.084000','2026-02-23 13:16:17.084000',20004,0,33178,'ASSET-CATEGORIES-NAVIGATION-MULTI-COLUMN-LAYOUT-FTL','1.0','<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Name language-id=\"sv_SE\">Layout med flera kolumner</Name><Name language-id=\"pt_BR\">Layout em Múltiplas Colunas</Name><Name language-id=\"ja_JP\">複数カラムレイアウト</Name><Name language-id=\"fr_FR\">Mise en page multi-colonne</Name><Name language-id=\"hu_HU\">Több oszlopos elrendezés</Name><Name language-id=\"de_DE\">Multi-Spalten-Layout</Name><Name language-id=\"ca_ES\">Plana multi-columna</Name><Name language-id=\"ar_SA\">تخطيط أعمدة متعددة</Name><Name language-id=\"fi_FI\">Usean sarakkeen asettelu</Name><Name language-id=\"en_US\">Multi Column Layout</Name><Name language-id=\"zh_CN\">多列布局</Name><Name language-id=\"es_ES\">Diseño con varias columnas</Name><Name language-id=\"nl_NL\">Lay-out met meerdere kolommen</Name></root>','<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Description language-id=\"sv_SE\">Visar en kolumn för varje ordlista. Varje kolumn inkluderar namnet på en ordlista med ordlistans toppnivåkategorier listade under.</Description><Description language-id=\"pt_BR\">Exibe uma coluna para cada vocabulário. Cada coluna inclui o nome do vocabulário com as categorias de nível mais alto listadas abaixo dele.</Description><Description language-id=\"ja_JP\">各ボキャブラリ用に列を表示する。各列は以下にリストになっている、最上位に設定されている用語名を含んでいます</Description><Description language-id=\"fr_FR\">Affiche une colonne pour chaque vocabulaire. Chaque colonne inclut le nom d\'un vocabulaire avec les catégories du niveau racine listées en dessous.</Description><Description language-id=\"hu_HU\">Megjelenít egy oszlopot minden szótár számára. Minden oszlop tartalmazza a szótár nevét, alatta a szótár felső szintű kategóriáival.</Description><Description language-id=\"de_DE\">Stellt eine Spalte für jedes Vokabular dar. Jede Spalte enthält den Namen eines Vokabulars mit der obersten Kategorienebene darunter.</Description><Description language-id=\"ca_ES\">Visualitza una columna per a cada vocabulari. Cada columna inclou el nom del vocabulari amb la categoria de nivell més alta a sota.</Description><Description language-id=\"ar_SA\">يعرض عمودًا لكل مفرد. يتضمن كل عمود اسم المفرد مع فئات المستوى الأعلى للمفردات المدرجة تحتها.</Description><Description language-id=\"fi_FI\">Näyttää sarakkeen jokaiselle sanastolle. Jokainen sarake sisältää sanaston nimen, missä sanaston ylätason luokitukset on listattu.</Description><Description language-id=\"en_US\">Displays a column for each vocabulary. Each column includes the name of a vocabulary with the vocabulary\'s top level categories listed underneath.</Description><Description language-id=\"zh_CN\">显示一列中的每个词汇，每列包括顶级类别之下的词汇名字。</Description><Description language-id=\"es_ES\">Despliega una columna para cada vocabulario. Cada columna incluye el nombre de un vocabulario con las categorías de mayor nivel del vocabulario listadas debajo.</Description><Description language-id=\"nl_NL\">Toon een kolom voor ieder woordenboek. Iedere kolom bevat de naam van een woordenboek met de hoofd categorieën eronder.</Description></root>','display',NULL,'ftl','<#assign hasCategories = false />\n\n<#if entries?has_content>\n	<@clay.row>\n		<#list entries as entry>\n			<#assign categories = entry.getCategories() />\n\n			<#if categories?has_content>\n				<#assign hasCategories = true />\n\n				<@clay.col md=\"3\">\n					<div class=\"results-header\">\n						<h3>\n							${entry.getUnambiguousTitle(entries, themeDisplay.getSiteGroupId(), themeDisplay.getLocale())}\n						</h3>\n					</div>\n\n					<@displayCategories categories = categories />\n				</@clay.col>\n			</#if>\n		</#list>\n\n		<#if !hasCategories>\n			${renderRequest.setAttribute(\"PORTLET_CONFIGURATOR_VISIBILITY\", true)}\n\n			<div class=\"alert alert-info w-100\">\n				<@liferay_ui.message key=\"there-are-no-categories\" />\n			</div>\n		</#if>\n	</@clay.row>\n</#if>\n\n<#macro displayCategories\n	categories\n>\n	<#if categories?has_content>\n		<ul class=\"categories\">\n			<#list categories as category>\n				<li>\n					<#assign categoryURL = renderResponse.createRenderURL() />\n\n					${categoryURL.setParameter(\"resetCur\", \"true\")}\n					${categoryURL.setParameter(\"categoryId\", category.getCategoryId()?string)}\n\n					<a href=\"${categoryURL}\">${category.getName()}</a>\n\n					<#if serviceLocator??>\n						<#assign\n							assetCategoryService = serviceLocator.findService(\"com.liferay.asset.kernel.service.AssetCategoryService\")\n\n							childCategories = assetCategoryService.getChildCategories(category.getCategoryId())\n						/>\n\n						<@displayCategories categories = childCategories />\n					</#if>\n				</li>\n			</#list>\n		</ul>\n	</#if>\n</#macro>',0,0,33196,NULL,NULL),(0,0,'b8d85aba-6e46-a01b-bd77-49d9512f0914','b8d85aba-6e46-a01b-bd77-49d9512f0914',33198,20120,39084709973119,20096,NULL,20096,NULL,'2026-02-23 13:16:17.445000','2026-02-23 13:16:17.445000',20006,0,33178,'ASSET-TAGS-NAVIGATION-COLOR-BY-POPULARITY-FTL','1.0','<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Name language-id=\"sv_SE\">Färga efter popularitet</Name><Name language-id=\"pt_BR\">Colorir por Popularidade</Name><Name language-id=\"ja_JP\">頻出度により色分けする</Name><Name language-id=\"fr_FR\">Couleur par popularité</Name><Name language-id=\"hu_HU\">Szín népszerűség alapján</Name><Name language-id=\"de_DE\">Nach Popularität färben</Name><Name language-id=\"ca_ES\">Color per popularitat</Name><Name language-id=\"ar_SA\">الألوان حسب الأولوية</Name><Name language-id=\"fi_FI\">Väri suosion mukaan</Name><Name language-id=\"en_US\">Color by Popularity</Name><Name language-id=\"zh_CN\">受欢迎的颜色</Name><Name language-id=\"es_ES\">Color por popularidad</Name><Name language-id=\"nl_NL\">Kleur op populariteit</Name></root>','<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Description language-id=\"sv_SE\">Visar tillgångstaggar färgade efter popularitet: röd (hög), gul (medelhög) och grön (låg).</Description><Description language-id=\"pt_BR\">Exibe marcadores coloridos por popularidade: vermelho (alta), amarelo (média) e verde (baixa).</Description><Description language-id=\"ja_JP\">アセットタグを人気順に表示する:赤(高い)、黄色（普通)、緑（低い）</Description><Description language-id=\"fr_FR\">Affiche les étiquettes d\'asset coloriées par popularité: rouge (élevé), jaune (moyen), et vert (bas).</Description><Description language-id=\"hu_HU\">Megjeleníti a tartalom címkéket népszerűség szerint színezve: vörös (magas), sárga (közepes), és zöld (alacsony).</Description><Description language-id=\"de_DE\">Schlagwörter nach Popularität färben: Rot (hoch), gelb (mittel), grün (niedrig).</Description><Description language-id=\"ca_ES\">Mostra les etiquetes per colors segons popularitat: vermell (alta), groga (mitjana) i verda (baixa).</Description><Description language-id=\"ar_SA\">يعرض علامات الأصول الملونة حسب الأولوية: الأحمر (مرتفع) والأصفر (متوسط) والأخضر (منخفض).</Description><Description language-id=\"fi_FI\">Näyttää sisältötageja, mitkä on väritetty suosion mukaan: punainen (korkea), keltainen (keskiverto) ja virheä (alhainen)</Description><Description language-id=\"en_US\">Displays asset tags colored by popularity: red (high), yellow (medium), and green (low).</Description><Description language-id=\"zh_CN\">显示资源标签颜色等级： 红色 (高), 黄色 (中), 绿色 (低).</Description><Description language-id=\"es_ES\">Muestra las etiquetas de contenido coloreadas según su popularidad : rojo (alta), amarilla (media) y verde (baja).</Description><Description language-id=\"nl_NL\">Toon content labels volgens populariteit: rood (hoog), geel (midden) en groen (laag).</Description></root>','display',NULL,'ftl','<#if entries?has_content>\n	<ul class=\"tag-items tag-list\">\n		<#assign\n			scopeGroupId = getterUtil.getLong(scopeGroupId, themeDisplay.getScopeGroupId())\n			classNameId = getterUtil.getLong(classNameId, 0)\n			scopedAssetCounts = assetTagsNavigationDisplayContext.getScopedAssetCounts()\n\n			maxCount = 1\n			minCount = 1\n		/>\n\n		<#list entries as entry>\n			<#if scopedAssetCounts??>\n				<#assign assetCount = scopedAssetCounts[entry.getName()] />\n			<#else>\n				<#assign assetCount = entry.getAssetCount() />\n			</#if>\n\n			<#if (assetCount > 0) || getterUtil.getBoolean(showZeroAssetCount)>\n				<#assign\n					maxCount = liferay.max(maxCount, assetCount)\n					minCount = liferay.min(minCount, assetCount)\n				/>\n			</#if>\n		</#list>\n\n		<#assign multiplier = 1 />\n\n		<#if maxCount != minCount>\n			<#assign multiplier = 3 / (maxCount - minCount) />\n		</#if>\n\n		<#list entries as entry>\n			<#if scopedAssetCounts??>\n				<#assign assetCount = scopedAssetCounts[entry.getName()] />\n			<#else>\n				<#assign assetCount = entry.getAssetCount() />\n			</#if>\n\n			<#if (assetCount > 0) || getterUtil.getBoolean(showZeroAssetCount)>\n				<li class=\"taglib-asset-tags-summary\">\n					<#assign popularity = (maxCount - (maxCount - (assetCount - minCount))) * multiplier />\n\n					<#if popularity < 1>\n						<#assign displayType = \"success\" />\n					<#elseif (popularity >= 1) && (popularity < 2)>\n						<#assign displayType = \"warning\" />\n					<#else>\n						<#assign displayType = \"danger\" />\n					</#if>\n\n					<#assign tagURL = renderResponse.createRenderURL() />\n\n					${tagURL.setParameter(\"resetCur\", \"true\")}\n					${tagURL.setParameter(\"tag\", entry.getName())}\n\n					<a class=\"label label-${displayType} tag\" href=\"${tagURL}\">\n						<span class=\"label-item label-item-expand\">${entry.getName()}</span>\n\n						<#if assetCount?? && getterUtil.getBoolean(showAssetCount)>\n							<span class=\"label-item label-item-after tag-asset-count\">(${assetCount})</span>\n						</#if>\n					</a>\n				</li>\n			</#if>\n		</#list>\n	</ul>\n\n	<br style=\"clear: both;\" />\n</#if>',0,0,33199,NULL,NULL),(0,0,'4077d0ff-3b57-2113-4c0d-b8ff8f3f216b','4077d0ff-3b57-2113-4c0d-b8ff8f3f216b',33202,20120,39084709973119,20096,NULL,20096,NULL,'2026-02-23 13:16:17.816000','2026-02-23 13:16:17.816000',33201,0,33178,'SIMILAR-RESULTS-COMPACT-FTL','1.0','<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Name language-id=\"sv_SE\">Kompakt layout</Name><Name language-id=\"pt_BR\">Layout compacto</Name><Name language-id=\"ja_JP\">コンパクトレイアウト</Name><Name language-id=\"fr_FR\">Disposition compacte</Name><Name language-id=\"hu_HU\">Kompakt elrendezés</Name><Name language-id=\"de_DE\">Kompaktes Layout</Name><Name language-id=\"ca_ES\">Disposició compacta</Name><Name language-id=\"ar_SA\">مخطط مضغوط</Name><Name language-id=\"fi_FI\">Tiivis Asettelu</Name><Name language-id=\"en_US\">Compact Layout</Name><Name language-id=\"zh_CN\">紧凑布局</Name><Name language-id=\"es_ES\">Diseño compacto</Name><Name language-id=\"nl_NL\">Compacte lay-out</Name></root>','<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Description language-id=\"sv_SE\">Visa bara titeln med liknande resultat.</Description><Description language-id=\"pt_BR\">Exibir apenas o título de resultados similares.</Description><Description language-id=\"ja_JP\">類似結果についてタイトルのみ表示します。</Description><Description language-id=\"fr_FR\">Afficher seulement l\'intitulé des résultats similaires.</Description><Description language-id=\"hu_HU\">A hasonló találatoknak csak a címét jelenítse meg.</Description><Description language-id=\"de_DE\">Nur den Titel ähnlicher Ergebnisse anzeigen.</Description><Description language-id=\"ca_ES\">Mostra només el títol dels resultats similars.</Description><Description language-id=\"ar_SA\">عرض فقط عنوان النتائج المتماثلة.</Description><Description language-id=\"fi_FI\">Näytä samanlaisista tuloksista vain otsikko.</Description><Description language-id=\"en_US\">Display only the title of similar results.</Description><Description language-id=\"zh_CN\">仅显示相似结果的标题。</Description><Description language-id=\"es_ES\">Muestra solo el título de resultados similares.</Description><Description language-id=\"nl_NL\">Alleen de titel van soortgelijke resultaten weergeven.</Description></root>','display',NULL,'ftl','<div class=\"display-compact\">\n	<ul>\n		<#if entries?has_content>\n			<#list entries as entry>\n				<li>\n					<a class=\"link-primary single-link\" href=\"${entry.getViewURL()}\">\n						${htmlUtil.escape(entry.getTitle())}\n					</a>\n				</li>\n			</#list>\n		</#if>\n	</ul>\n</div>',0,0,33203,NULL,NULL),(0,0,'6adcd37d-afc9-8ad6-da51-3d6ce9142c7d','6adcd37d-afc9-8ad6-da51-3d6ce9142c7d',33205,20120,39084709973119,20096,NULL,20096,NULL,'2026-02-23 13:16:17.824000','2026-02-23 13:16:17.824000',33201,0,33178,'SIMILAR-RESULTS-LIST-FTL','1.0','<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Name language-id=\"sv_SE\">Listlayout</Name><Name language-id=\"pt_BR\">Layout da lista</Name><Name language-id=\"ja_JP\">リストレイアウト</Name><Name language-id=\"fr_FR\">Disposition en liste</Name><Name language-id=\"hu_HU\">Lista elrendezés</Name><Name language-id=\"de_DE\">Listenlayout</Name><Name language-id=\"ca_ES\">Disposició de la llista</Name><Name language-id=\"ar_SA\">مخطط القائمة</Name><Name language-id=\"fi_FI\">Luetteloasettelu</Name><Name language-id=\"en_US\">List Layout</Name><Name language-id=\"zh_CN\">列表布局</Name><Name language-id=\"es_ES\">Diseño de lista</Name><Name language-id=\"nl_NL\">Lijstlay-out</Name></root>','<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Description language-id=\"sv_SE\">Visa titeln, skaparens användarnamn, skapandedatum, tillgångstyp och beskrivning.</Description><Description language-id=\"pt_BR\">Exibir o título, nome de usuário do criador, data de criação, tipo de conteúdo e descrição.</Description><Description language-id=\"ja_JP\">タイトル、作成者のユーザー名、作成日、アセットタイプ、説明を表示します。</Description><Description language-id=\"fr_FR\">Afficher l\'intitulé, le nom d\'utilisateur du créateur, la date de création, le type d\'actif et la description.</Description><Description language-id=\"hu_HU\">Jelenítse meg a címet, a készítő felhasználónevét, a létrehozás dátumát, a tartalomtípust és a leírást.</Description><Description language-id=\"de_DE\">Titel, Benutzername des Erstellers, Erstellungsdatum. Assettyp und Beschreibung anzeigen.</Description><Description language-id=\"ca_ES\">Mostra el títol, el nom d\'usuari del creador, la data de creació, el tipus de contingut i la descripció.</Description><Description language-id=\"ar_SA\">عرض العنوان واسم المستخدم المنشئ وتاريخ الإنشاء ونوع الأصل والوصف.</Description><Description language-id=\"fi_FI\">Näytä otsikko, luojan käyttjänimi, luontipäivä, sisällön tyyppi ja kuvaus.</Description><Description language-id=\"en_US\">Display the title, creator\'s user name, creation date, asset type, and description.</Description><Description language-id=\"zh_CN\">显示标题、创建者的用户名、创建日期、资源类型和描述。</Description><Description language-id=\"es_ES\">Muestra el título, el nombre de usuario del autor, la fecha de creación, el tipo de activo y la descripción.</Description><Description language-id=\"nl_NL\">De titel, de gebruikersnaam van de maker, de aanmaakdatum, het assettype en de beschrijving weergeven.</Description></root>','display',NULL,'ftl','<div class=\"display-list\">\n	<ul class=\"list-group\">\n		<#if entries?has_content>\n			<#list entries as entry>\n				<li class=\"list-group-item list-group-item-flex\">\n					<div class=\"autofit-col\">\n						<div class=\"sticker sticker-secondary\">\n							<@clay.icon symbol=\"${entry.getIconId()}\" />\n						</div>\n					</div>\n\n					<div class=\"autofit-col autofit-col-expand\">\n						<section class=\"autofit-section\">\n							<div class=\"list-group-title\">\n								<a href=\"${entry.getViewURL()}\" title=\"${htmlUtil.escape(entry.getTitle())}\">\n									${htmlUtil.escape(entry.getTitle())}\n								</a>\n							</div>\n\n							<div class=\"similar-results-metadata\">\n								<p class=\"list-group-subtext\">\n									<#if (entry.getCreatorUserName()??) && validator.isNotNull(entry.getCreatorUserName())>\n										<span class=\"subtext-item\">\n											${htmlUtil.escape(entry.getCreatorUserName())}\n										</span>\n									</#if>\n\n									<#if (entry.getCreationDateString()??) && validator.isNotNull(entry.getCreationDateString())>\n										<span class=\"subtext-item\">\n											${entry.getCreationDateString()}\n										</span>\n									</#if>\n								</p>\n\n								<p class=\"list-group-subtext\">\n									${entry.getModelResource()}\n								</p>\n							</div>\n\n							<p class=\"list-group-text similar-results-description\">\n								${htmlUtil.escape(entry.getContent())}\n							</p>\n						</section>\n					</div>\n				</li>\n			</#list>\n		</#if>\n	</ul>\n</div>',0,0,33206,NULL,NULL),(0,0,'2ad8a0c1-4259-8346-d159-eaaac686b4a9','2ad8a0c1-4259-8346-d159-eaaac686b4a9',33208,20120,39084709973119,20096,NULL,20096,NULL,'2026-02-23 13:16:17.833000','2026-02-23 13:16:17.833000',33201,0,33178,'SIMILAR-RESULTS-CARD-FTL','1.0','<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Name language-id=\"sv_SE\">Kortlayout</Name><Name language-id=\"pt_BR\">Layout do cartão</Name><Name language-id=\"ja_JP\">カードレイアウト</Name><Name language-id=\"fr_FR\">Disposition de la carte</Name><Name language-id=\"hu_HU\">Kártyaelrendezés</Name><Name language-id=\"de_DE\">Kartenlayout</Name><Name language-id=\"ca_ES\">Disposició de la targeta</Name><Name language-id=\"ar_SA\">مخطط البطاقة</Name><Name language-id=\"fi_FI\">Kortin Asettelu</Name><Name language-id=\"en_US\">Card Layout</Name><Name language-id=\"zh_CN\">卡片布局</Name><Name language-id=\"es_ES\">Diseño de tarjeta</Name><Name language-id=\"nl_NL\">Kaartlay-out</Name></root>','<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Description language-id=\"sv_SE\">Visa liknande resultat som ett rutnät med kort.</Description><Description language-id=\"pt_BR\">Exibir resultados similares como uma série de cartões.</Description><Description language-id=\"ja_JP\">類似結果をグリッド状に配置したカードで表示します。</Description><Description language-id=\"fr_FR\">Afficher les résultats similaires sous la forme de grille de cartes.</Description><Description language-id=\"hu_HU\">A hasonló eredményeket jelenítse meg kártyarácsként.</Description><Description language-id=\"de_DE\">Ähnliche Ergebnisse als Kartengitter anzeigen.</Description><Description language-id=\"ca_ES\">Mostra els resultats similars com una sèrie de cartes.</Description><Description language-id=\"ar_SA\">عرض النتائج المتماثلة كشبكة من البطاقات.</Description><Description language-id=\"fi_FI\">Näytä samanlaiset tulokset korttien ruudukkona.</Description><Description language-id=\"en_US\">Display similar results as a grid of cards.</Description><Description language-id=\"zh_CN\">将相似结果显示为卡片网格。</Description><Description language-id=\"es_ES\">Muestra resultados similares como una cuadrícula de tarjetas.</Description><Description language-id=\"nl_NL\">Soortgelijke resultaten weergeven als een kaartenrooster.</Description></root>','display',NULL,'ftl','<div class=\"display-card\">\n	<ul class=\"card-page\">\n		<#if entries?has_content>\n			<#list entries as entry>\n				<li class=\"card-page-item card-page-item-asset\">\n					<div class=\"card card-type-asset file-card\">\n						<div class=\"aspect-ratio card-item-first\">\n							<#if (entry.getThumbnailURLString()??) && validator.isNotNull(entry.getThumbnailURLString())>\n								<img alt=\"${htmlUtil.escape(entry.getTitle())}\" class=\"aspect-ratio-item aspect-ratio-item-center-middle aspect-ratio-item-vertical-fluid\" src=\"${entry.getThumbnailURLString()}\" />\n							<#else>\n								<div class=\"aspect-ratio-item aspect-ratio-item-center-middle aspect-ratio-item-vertical-fluid card-type-asset-icon\">\n									<@clay.icon symbol=\"${entry.getIconId()}\" />\n								</div>\n							</#if>\n						</div>\n\n						<div class=\"card-body\">\n							<div class=\"card-row\">\n								<div class=\"autofit-col autofit-col-expand\">\n									<section class=\"autofit-section\">\n										<#if (entry.getCategoriesString()??) && validator.isNotNull(entry.getCategoriesString())>\n											<span class=\"card-category text-truncate-inline\">\n												${entry.getCategoriesString()}\n											</span>\n										</#if>\n\n										<h3 class=\"card-title\" title=\"${htmlUtil.escape(entry.getTitle())}\">\n											<a href=\"${entry.getViewURL()}\">\n												${htmlUtil.escape(entry.getTitle())}\n											</a>\n										</h3>\n\n										<#if (entry.getCreatorUserName()??) && validator.isNotNull(entry.getCreatorUserName())>\n											<p class=\"card-subtitle\">\n												<span class=\"text-truncate-inline\">\n													<span class=\"text-truncate\">\n														${htmlUtil.escape(entry.getCreatorUserName())}\n													</span>\n												</span>\n											</p>\n										</#if>\n\n										<#if (entry.getCreationDateString()??) && validator.isNotNull(entry.getCreationDateString())>\n											<p class=\"card-subtitle\">\n												<span class=\"text-truncate-inline\">\n													<span class=\"text-truncate\">\n														${entry.getCreationDateString()}\n													</span>\n												</span>\n											</p>\n										</#if>\n\n										<p class=\"card-subtitle\">\n											<span class=\"text-truncate-inline\">\n												<span class=\"text-truncate\">\n													${entry.getModelResource()}\n												</span>\n											</span>\n										</p>\n\n										<div class=\"card-description\">\n											${htmlUtil.escape(entry.getContent())}\n										</div>\n									</section>\n								</div>\n							</div>\n						</div>\n					</div>\n				</li>\n			</#list>\n		</#if>\n	</ul>\n</div>',0,0,33209,NULL,NULL),(0,0,'2c97c8c0-e547-4f0c-112e-ad57d7d0c152','2c97c8c0-e547-4f0c-112e-ad57d7d0c152',33212,20120,39084709973119,20096,NULL,20096,NULL,'2026-02-23 13:16:19.037000','2026-02-23 13:16:19.037000',33211,0,33178,'COMMERCE-ORDER-ITEM-MINI-BASIC-FTL','1.0','<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Name language-id=\"sv_SE\">Standard</Name><Name language-id=\"pt_BR\">Básico</Name><Name language-id=\"ja_JP\">通常の検索に戻る</Name><Name language-id=\"fr_FR\">Basique</Name><Name language-id=\"hu_HU\">Egyszerű</Name><Name language-id=\"de_DE\">Einfach</Name><Name language-id=\"ca_ES\">Bàsic</Name><Name language-id=\"ar_SA\">أساسي</Name><Name language-id=\"fi_FI\">Perus</Name><Name language-id=\"en_US\">Basic</Name><Name language-id=\"zh_CN\">基本的</Name><Name language-id=\"es_ES\">Básico</Name><Name language-id=\"nl_NL\">Basis</Name></root>','<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Description language-id=\"sv_SE\">Visa rubriker, författare och sammanfattningar kompakt för blogginlägg.</Description><Description language-id=\"pt_BR\">Exibe títulos, autores e resumos compactamente para posts de blog.</Description><Description language-id=\"ja_JP\">タイトル、作成者、要約は、ブログエントリー用に小さくまとめられます</Description><Description language-id=\"fr_FR\">Affiche titres, auteurs, et abstraits de manière compacte pour les entrées de blog.</Description><Description language-id=\"hu_HU\">Megjeleníti kompakt módon a címeket, szerzőket és kivonatokat a blog bejegyzésekhez.</Description><Description language-id=\"de_DE\">Kompakte Darstellung von Titel, Autoren und Kurzfassungen für Blogeinträge.</Description><Description language-id=\"ca_ES\">Mostra els titles, autors i resums de forma compacta per les entrades del blog.</Description><Description language-id=\"ar_SA\">يعرض العناوين والمؤلفين والملخصات لإدخالات المدونات بشكل مضغوط.</Description><Description language-id=\"fi_FI\">Näyttää blogien otsikot, tekijät ja lyhenteet lyhyesti</Description><Description language-id=\"en_US\">Displays titles, authors, and abstracts compactly for blog entries.</Description><Description language-id=\"zh_CN\">简介显示博客的名字，作者和摘要。</Description><Description language-id=\"es_ES\">Muestra de forma compacta títulos, autores y resúmenes para las entradas del blog.</Description><Description language-id=\"nl_NL\">Geeft titels, auteurs en samenvatting compact weer voor blogs.</Description></root>','display',NULL,'ftl','<#assign count = 0 />\n\n<#if entries?has_content>\n	<div class=\"row\">\n		<#assign\n			orderPrice = commerceCartContentMiniDisplayContext.getCommerceOrderPrice()\n\n			subTotal = orderPrice.getSubtotal()\n		/>\n\n		<div class=\"col-md-12\">\n			<strong>Total: ${subTotal.format(themeDisplay.getLocale())}</strong>\n		</div>\n\n		<#list entries as curCommerceOrderItem>\n			<#assign\n				cpDefinition = curCommerceOrderItem.getCPDefinition()\n\n				image = \'\'\n\n				productURL = commerceCartContentMiniDisplayContext.getCPDefinitionURL(cpDefinition.getCPDefinitionId(), themeDisplay)\n\n				name = cpDefinition.getName(themeDisplay.getLanguageId())\n			/>\n\n			<#if commerceCartContentMiniDisplayContext.getCommerceOrderItemThumbnailSrc(curCommerceOrderItem)??>\n				<#assign\n					image = commerceCartContentMiniDisplayContext.getCommerceOrderItemThumbnailSrc(curCommerceOrderItem)\n				/>\n			</#if>\n\n			<div class=\"col-md-6\">\n				<div class=\"row-fluid\">\n					<img class=\"w-100\" src=\"${htmlUtil.escapeAttribute(image)}\">\n				</div>\n\n				<div class=\"row-fluid\">\n					<a href=\"${htmlUtil.escapeAttribute(productURL)}\">\n						<strong>${htmlUtil.escape(name)}</strong>\n					</a>\n\n					<div class=\"commerce-price-section d-inline float-right\">\n						<@commerce_ui[\"price\"]\n							CPDefinitionId=cpDefinition.getCPDefinitionId()\n							CPInstanceId=curCommerceOrderItem.getCPInstanceId()\n							showDiscount=false\n						/>\n					</div>\n				</div>\n			</div>\n\n			<#assign count = count + 1 />\n\n			<#if count gte 2>\n				</div>\n\n				<div class=\"row\">\n\n				<#assign count = 0 />\n			</#if>\n		</#list>\n	</div>\n</#if>',0,0,33213,NULL,NULL),(0,0,'e2b6c196-40d3-0f51-644f-f5f739a365ae','e2b6c196-40d3-0f51-644f-f5f739a365ae',33216,20120,39084709973119,20096,NULL,20096,NULL,'2026-02-23 13:16:19.415000','2026-02-23 13:16:19.415000',33215,0,33178,'COMMERCE-ORDER-ITEM-BASIC-FTL','1.0','<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Name language-id=\"sv_SE\">Standard</Name><Name language-id=\"pt_BR\">Básico</Name><Name language-id=\"ja_JP\">通常の検索に戻る</Name><Name language-id=\"fr_FR\">Basique</Name><Name language-id=\"hu_HU\">Egyszerű</Name><Name language-id=\"de_DE\">Einfach</Name><Name language-id=\"ca_ES\">Bàsic</Name><Name language-id=\"ar_SA\">أساسي</Name><Name language-id=\"fi_FI\">Perus</Name><Name language-id=\"en_US\">Basic</Name><Name language-id=\"zh_CN\">基本的</Name><Name language-id=\"es_ES\">Básico</Name><Name language-id=\"nl_NL\">Basis</Name></root>','<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Description language-id=\"sv_SE\">Visa rubriker, författare och sammanfattningar kompakt för blogginlägg.</Description><Description language-id=\"pt_BR\">Exibe títulos, autores e resumos compactamente para posts de blog.</Description><Description language-id=\"ja_JP\">タイトル、作成者、要約は、ブログエントリー用に小さくまとめられます</Description><Description language-id=\"fr_FR\">Affiche titres, auteurs, et abstraits de manière compacte pour les entrées de blog.</Description><Description language-id=\"hu_HU\">Megjeleníti kompakt módon a címeket, szerzőket és kivonatokat a blog bejegyzésekhez.</Description><Description language-id=\"de_DE\">Kompakte Darstellung von Titel, Autoren und Kurzfassungen für Blogeinträge.</Description><Description language-id=\"ca_ES\">Mostra els titles, autors i resums de forma compacta per les entrades del blog.</Description><Description language-id=\"ar_SA\">يعرض العناوين والمؤلفين والملخصات لإدخالات المدونات بشكل مضغوط.</Description><Description language-id=\"fi_FI\">Näyttää blogien otsikot, tekijät ja lyhenteet lyhyesti</Description><Description language-id=\"en_US\">Displays titles, authors, and abstracts compactly for blog entries.</Description><Description language-id=\"zh_CN\">简介显示博客的名字，作者和摘要。</Description><Description language-id=\"es_ES\">Muestra de forma compacta títulos, autores y resúmenes para las entradas del blog.</Description><Description language-id=\"nl_NL\">Geeft titels, auteurs en samenvatting compact weer voor blogs.</Description></root>','display',NULL,'ftl','<div class=\"table-responsive\">\n	<table class=\"table\">\n		<#if entries?has_content>\n			<tr>\n				<th>${languageUtil.get(request, \"product\")}</th>\n				<th>${languageUtil.get(request, \"description\")}</th>\n				<th>${languageUtil.get(request, \"price\")}</th>\n				<th>${languageUtil.get(request, \"quantity\")}</th>\n				<th></th>\n			</tr>\n\n			<#list entries as curCommerceOrderItem>\n				<#assign\n					cpDefinition = curCommerceOrderItem.getCPDefinition()\n\n					image = \'\'\n\n					productURL = commerceCartContentDisplayContext.getCPDefinitionURL(cpDefinition.getCPDefinitionId(), themeDisplay)\n\n					name = cpDefinition.getName(themeDisplay.getLanguageId())\n\n					deleteURL = commerceCartContentDisplayContext.getDeleteURL(curCommerceOrderItem)\n				/>\n\n				<#if commerceCartContentDisplayContext.getCommerceOrderItemThumbnailSrc(curCommerceOrderItem)??>\n					<#assign\n						image = commerceCartContentDisplayContext.getCommerceOrderItemThumbnailSrc(curCommerceOrderItem)\n					/>\n				</#if>\n\n				<tr>\n					<td>\n						<#if image?has_content>\n							<img class=\"aspect-ratio-bg-cover sticker sticker-lg sticker-static\" src=\"${htmlUtil.escapeAttribute(image)}\">\n						</#if>\n					</td>\n					<td>\n						<a href=\"${htmlUtil.escapeAttribute(productURL)}\">\n							<strong>${htmlUtil.escape(name)}</strong>\n						</a>\n					</td>\n					<td>\n						<@commerce_ui[\"price\"]\n							CPDefinitionId=cpDefinition.getCPDefinitionId()\n							CPInstanceId=curCommerceOrderItem.getCPInstanceId()\n							showDiscount=false\n						/>\n					</td>\n					<td>${curCommerceOrderItem.getQuantity()}</td>\n					<td>\n						<a href=\"${htmlUtil.escapeAttribute(deleteURL)}\">\n							${languageUtil.get(request, \"delete\")}\n						</a>\n					</td>\n				</tr>\n			</#list>\n		</#if>\n	</table>\n</div>',0,0,33217,NULL,NULL),(0,0,'ae8cb02d-982e-1054-9633-f2676b1b23eb','ae8cb02d-982e-1054-9633-f2676b1b23eb',33220,20120,39084709973119,20096,NULL,20096,NULL,'2026-02-23 13:16:19.814000','2026-02-23 13:16:19.814000',33219,0,33178,'COMMERCE-ORDER-ITEM-TOTAL-BASIC-FTL','1.0','<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Name language-id=\"sv_SE\">Standard</Name><Name language-id=\"pt_BR\">Básico</Name><Name language-id=\"ja_JP\">通常の検索に戻る</Name><Name language-id=\"fr_FR\">Basique</Name><Name language-id=\"hu_HU\">Egyszerű</Name><Name language-id=\"de_DE\">Einfach</Name><Name language-id=\"ca_ES\">Bàsic</Name><Name language-id=\"ar_SA\">أساسي</Name><Name language-id=\"fi_FI\">Perus</Name><Name language-id=\"en_US\">Basic</Name><Name language-id=\"zh_CN\">基本的</Name><Name language-id=\"es_ES\">Básico</Name><Name language-id=\"nl_NL\">Basis</Name></root>','<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_S