${navbarId}\">\n		<ul aria-label=\"<@liferay.language key=\"site-pages\" />\" class=\"nav nav-justified nav-pills navbar-site\" role=\"menubar\">\n			<#assign navItems = entries />\n\n			<#list navItems as navItem>\n				<#assign\n					displayIcon = navItem.getDisplayIcon()\n					showChildrenNavItems = (displayDepth != 1) && navItem.hasBrowsableChildren()\n				/>\n\n				<#if navItem.isBrowsable() || showChildrenNavItems>\n					<#assign\n						nav_item_attr_has_popup = \"\"\n						nav_item_caret = \"\"\n						nav_item_css_class = \"lfr-nav-item nav-item\"\n						nav_item_href_link = \"\"\n						nav_item_link_css_class = \"nav-link text-truncate\"\n					/>\n\n					<#if showChildrenNavItems>\n						<#assign nav_item_attr_has_popup = \"aria-haspopup=\'true\'\" />\n\n						<#assign nav_item_caret>\n							<span class=\"lfr-nav-child-toggle\">\n								<@clay[\"icon\"] symbol=\"angle-down\" />\n							</span>\n						</#assign>\n\n						<#assign\n							nav_item_css_class = \"${nav_item_css_class} dropdown\"\n							nav_item_link_css_class = \"${nav_item_link_css_class} dropdown-toggle\"\n						/>\n					</#if>\n\n					<#if navItem.isBrowsable()>\n						<#assign nav_item_href_link = \"href=\'${navItem.getURL()}\'\" />\n					</#if>\n\n					<#if navItem.isChildSelected() || navItem.isSelected()>\n						<#assign\n							nav_item_css_class = \"${nav_item_css_class} selected active\"\n						/>\n					</#if>\n\n					<li class=\"${nav_item_css_class}\" id=\"layout_${portletDisplay.getId()}_${navItem.getLayoutId()}\" role=\"presentation\">\n						<a ${nav_item_attr_has_popup} class=\"${nav_item_link_css_class}\" ${nav_item_href_link} ${navItem.getTarget()} role=\"menuitem\">\n							<span class=\"text-truncate\">\n								<#if validator.isNull(displayIcon)>\n									<@liferay_theme[\"layout-icon\"] layout=navItem.getLayout() />\n								<#else>\n									<@clay[\"icon\"] symbol=\"${displayIcon}\" />\n								</#if>\n\n								${navItem.getName()} ${nav_item_caret}\n							</span>\n						</a>\n\n						<#if showChildrenNavItems>\n							<ul aria-expanded=\"false\" class=\"child-menu dropdown-menu\" role=\"menu\">\n								<@buildChildrenNavItems\n									displayDepth = displayDepth\n									navItem = navItem\n								/>\n							</ul>\n						</#if>\n					</li>\n				</#if>\n			</#list>\n		</ul>\n	</div>\n\n	<@liferay_aui.script use=\"liferay-navigation-interaction\">\n		var navigation = A.one(\'#${navbarId}\');\n\n		Liferay.Data.NAV_INTERACTION_LIST_SELECTOR = \'.navbar-site\';\n		Liferay.Data.NAV_LIST_SELECTOR = \'.navbar-site\';\n\n		if (navigation) {\n			navigation.plug(Liferay.NavigationInteraction);\n		}\n	</@>\n</#if>',0,20096,NULL,'2026-02-23 13:16:36.735000'),(0,0,33375,20120,39084709973119,20096,NULL,'2026-02-23 13:16:36.743000',33363,0,33373,'1.0','<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Name language-id=\"sv_SE\">Piller staplat</Name><Name language-id=\"pt_BR\">Pills empilhados</Name><Name language-id=\"ja_JP\">縦積みピル形式</Name><Name language-id=\"fr_FR\">Pilules empilées</Name><Name language-id=\"hu_HU\">Feltornyozott tabletták</Name><Name language-id=\"de_DE\">Pills gestapelt</Name><Name language-id=\"ca_ES\">Càpsules apilades</Name><Name language-id=\"ar_SA\">أزرار مكدسة</Name><Name language-id=\"fi_FI\">Pills Pinottu</Name><Name language-id=\"en_US\">Pills Stacked</Name><Name language-id=\"zh_CN\">堆叠药丸</Name><Name language-id=\"es_ES\">Globos apilados</Name><Name language-id=\"nl_NL\">Gestapelde pillen</Name></root>','<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Description language-id=\"sv_SE\">Visar en navigeringsmeny med staplade navigeringsobjekt som visas som piller.</Description><Description language-id=\"pt_BR\">Exibe um menu de navegação com itens de navegação empilhados exibidos como pills.</Descriptio