INSERT INTO `notificationtemplate` VALUES (0,'0c1e17b2-7924-372c-00a5-c81328fc1f43','L_COMMERCE_ORDER_TEMPLATE',31602,39084709973119,20123,'Test Test','2026-02-23 13:09:16.819000','2026-02-23 13:09:16.819000',0,'<?xml version=\"1.0\" ?><root available-locales=\"en_US\" default-locale=\"en_US\"><Body language-id=\"en_US\">&lt;html&gt;\n&lt;head&gt;\n	&lt;meta content=\"width=device-width, initial-scale=1\" name=\"viewport\" /&gt;\n	&lt;style type=\"text/css\"&gt;\n		html, body {\n			background-color: #FFF;\n			color: #272833;\n			margin: 0;\n			padding: 0;\n			width: 100%;\n		}\n		.banner {\n			background: linear-gradient(120deg, #011181 0%,#0c6297 45%,#0c6297 50%,#7eefec 100%);\n			border-radius: 8px 8px 0 0;\n			height: 56px;\n		}\n		.container {\n			background-color: #F7F8F9;\n			border-radius: 20px;\n			box-sizing: border-box;\n			font-family: \'Roboto\', sans-serif;\n			font-size: 14px;\n			margin: 48px auto;\n			max-width: 640px;\n			min-width: 320px;\n			overflow: hidden;\n			padding: 32px 48px;\n		}\n		.content {\n			box-sizing: border-box;\n			margin-top: 14px;\n		}\n		.footer {\n			color: #6B6C7E;\n			font-size: 14px;\n			line-height: 21px;\n			text-align: center;\n		}\n		.section {\n			background-color: #FFF;\n			border-radius: 8px;\n			margin-bottom: 24px;\n			overflow: hidden;\n			padding-bottom: 1px;\n		}\n		.order-address-section, \n		.order-confirmation-section, \n		.order-details-section, \n		.order-items-section {\n			border-bottom: 1px solid #E7E7ED;\n			margin: 0 24px;\n			padding: 0 0 24px;\n		}\n		.order-confirmation-section h3 {\n			font-size: 18px;\n			font-weight: 500;\n			margin: 20px 0;\n		}\n		.help-section h4,\n		.order-address-section h4, \n		.order-details-section h4, \n		.order-items-section h4,\n		.order-items-section h4,\n		.order-items-section th {\n			font-size: 16px;\n			font-weight: 600;\n			margin: 20px 0;\n			text-align:left;\n		}\n		.help-section {\n			padding: 1px 24px 8px;\n		}\n		.order-summary-section {\n			background-color: #F0F5FF;\n			border-radius: 8px;\n			margin: 24px;\n			padding: 24px;\n			text-align: right;\n		}\n		.order-summary-section div {\n			line-height: 18px;\n		}\n		.summary-helper {\n			font-size: 12px;\n		}\n		.order-items,\n		.order-items table {\n			width: 100%;\n		}\n		.order-item-info th {\n			margin-bottom: 5px;\n			text-align:left;\n		}\n		.order-item-price table {\n			text-align: right;\n		}\n		.order-item-price td {\n			white-space: nowrap;\n		}\n		.order-item-discount-price {\n			color:#FF0000;\n		}\n		.order-item-info {\n			padding-right: 16px;\n			vertical-align: top;\n		}\n		.order-item-info td {\n			font-size: 12px;\n		}\n		.order-item-info-label {\n			display: block;\n		}\n		.order-item-info-label td:first-child {\n			font-weight: bold;\n			padding: 0;\n		}\n		.order-item-original-price {\n			text-decoration: line-through;\n		}\n		.order-item-price {\n			font-size: 16px;\n			font-weight: bold;\n			vertical-align: top;\n		}\n		.order-item-title {\n			font-size: 16px;\n			padding: 0px;\n			text-align: left;\n		}\n		.order-items {\n			border-collapse: inherit;\n			border-spacing: 0 16px;\n			text-align: left;\n		}\n		@media only screen and (max-width: 640px) {\n			.container { \n				margin: 0 auto !important;\n				padding: 24px !important;\n			}\n			.order-items .order-item-img {\n				height: 60px !important;\n				vertical-align: top !important;\n				width: 60px !important;\n			}\n			.order-items .order-item-img img {\n				max-height: 60px !important;\n				max-width: 60px !important;\n			}\n			.order-item-info {\n				max-width: 80% !important;\n			}\n		}\n	&lt;/style&gt;&lt;/head&gt;&lt;body&gt;\n		&lt;div class=\"container\"&gt;\n			&lt;div class=\"content\"&gt;\n				&lt;div class=\"section\"&gt;\n					&lt;div class=\"banner\"&gt;&amp;nbsp;&lt;/div&gt;\n\n					&lt;div class=\"order-confirmation-section\"&gt;\n						&lt;h3&gt;Order confirmation&lt;/h3&gt;\n\n						&lt;div&gt;Hi, [%COMMERCEORDER_AUTHOR_PREFIX%] &lt;b&gt;[%COMMERCEORDER_AUTHOR_FIRST_NAME%] [%COMMERCEORDER_AUTHOR_LAST_NAME%]&lt;/b&gt; [%COMMERCEORDER_AUTHOR_SUFFIX%]&lt;br /&gt;\n						Thank you for your order! Here is your order summary and delivery details. We will prepare your order as soon as possible and you will receive another email when it has been shipped.&lt;/div&gt;\n					&lt;/div&gt;\n\n					&lt;div class=\"order-details-section\"&gt;\n						&lt;h4&gt;Order details&lt;/h4&gt;\n\n						&lt;div&gt;\n							&lt;div&gt;&lt;b&gt;Order Number&lt;/b&gt;: #[%COMMERCEORDER_ID%]&lt;/div&gt;\n\n							&lt;div&gt;&lt;b&gt;Order Date&lt;/b&gt;: [%COMMERCEORDER_ORDERDATE%]&lt;/div&gt;\n\n							&lt;div&gt;&lt;b&gt;Account&lt;/b&gt;: [%COMMERCEORDER_ACCOUNT_NAME%] - #[%COMMERCEORDER_ACCOUNTID%]&lt;/div&gt;\n						&lt;/div&gt;\n					&lt;/div&gt;\n\n					&lt;div class=\"order-address-section\"&gt;\n						&lt;h4&gt;Address&lt;/h4&gt;\n\n						&lt;div&gt;\n							&lt;div&gt;&lt;b&gt;Billing Address&lt;/b&gt;: [%COMMERCEORDER_BILLING_ADDRESS_STREET1%] [%COMMERCEORDER_BILLING_ADDRESS_STREET2%] [%COMMERCEORDER_BILLING_ADDRESS_STREET3%], [%COMMERCEORDER_BILLING_ADDRESS_ZIP%] [%COMMERCEORDER_BILLING_ADDRESS_CITY%], [%COMMERCEORDER_BILLING_ADDRESS_REGION%] [%COMMERCEORDER_BILLING_ADDRESS_COUNTRY%]&lt;/div&gt;\n\n							&lt;div&gt;&lt;b&gt;Shipping Address&lt;/b&gt;: [%COMMERCEORDER_SHIPPING_ADDRESS_STREET1%] [%COMMERCEORDER_SHIPPING_ADDRESS_STREET2%] [%COMMERCEORDER_SHIPPING_ADDRESS_STREET3%], [%COMMERCEORDER_SHIPPING_ADDRESS_ZIP%] [%COMMERCEORDER_SHIPPING_ADDRESS_CITY%], [%COMMERCEORDER_SHIPPING_ADDRESS_REGION%] [%COMMERCEORDER_SHIPPING_ADDRESS_COUNTRY%]&lt;/div&gt;\n						&lt;/div&gt;\n					&lt;/div&gt;\n\n					&lt;div class=\"order-items-section\"&gt;\n						&lt;div&gt;[%COMMERCEORDER_ORDER_ITEMS%]&lt;/div&gt;\n					&lt;/div&gt;\n\n					&lt;div class=\"order-summary-section\"&gt;\n						&lt;div&gt;&lt;b&gt;Total: [%COMMERCEORDER_TOTALFORMATTED%]&lt;/b&gt;&lt;/div&gt;\n\n						&lt;div class=\"summary-helper\"&gt;Including Tax&lt;/div&gt;\n					&lt;/div&gt;\n				&lt;/div&gt;\n			&lt;/div&gt;\n\n			&lt;div class=\"section\"&gt;\n				&lt;div class=\"help-section\"&gt;\n					&lt;h4&gt;Do you need help?&lt;/h4&gt;\n\n					&lt;p&gt;If you have any questions, please contact us.&lt;/p&gt;\n				&lt;/div&gt;\n			&lt;/div&gt;\n\n			&lt;div class=\"footer\"&gt;\n				&lt;div&gt;Copyright © 2024&lt;/div&gt;\n			&lt;/div&gt;\n		&lt;/div&gt;\n	&lt;/body&gt;\n	&lt;/html&gt;</Body></root>',NULL,'richText','Commerce Order Notification','email','<?xml version=\"1.0\" ?><root available-locales=\"en_US\" default-locale=\"en_US\"><Subject language-id=\"en_US\">Order #[%COMMERCEORDER_ID%]</Subject></root>',0,'email');
