INSERT INTO `role_` VALUES (0,0,'19203283-3ffc-f08f-4e36-c62ef35134df','19203283-3ffc-f08f-4e36-c62ef35134df',20100,39084709973119,20096,NULL,'2026-02-23 13:07:44.379000','2026-02-23 13:07:44.379000',20065,20100,'Administrator',NULL,'<?xml version=\"1.0\" ?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">Administrators are super users who can do anything.</Description></root>',1,NULL),(0,0,'77ae716f-571b-bcd3-c98d-ee9074607ef1','77ae716f-571b-bcd3-c98d-ee9074607ef1',20101,39084709973119,20096,NULL,'2026-02-23 13:07:44.420000','2026-02-23 13:07:44.420000',20065,20101,'Analytics Administrator',NULL,'<?xml version=\"1.0\" ?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">Analytics Administrators are users who can view data across the company but cannot make changes except to the company preferences.</Description></root>',1,NULL),(0,0,'5d948219-6d66-7146-8ecd-1aad2f7c94be','5d948219-6d66-7146-8ecd-1aad2f7c94be',20102,39084709973119,20096,NULL,'2026-02-23 13:07:44.489000','2026-02-23 13:07:44.489000',20065,20102,'Guest',NULL,'<?xml version=\"1.0\" ?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">Unauthenticated users always have this role.</Description></root>',1,NULL),(0,0,'a2999f05-b51b-52e4-4173-3180ed13de63','a2999f05-b51b-52e4-4173-3180ed13de63',20103,39084709973119,20096,NULL,'2026-02-23 13:07:44.500000','2026-02-23 13:07:44.500000',20065,20103,'Owner',NULL,'<?xml version=\"1.0\" ?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">This is an implied role with respect to the objects users create.</Description></root>',1,NULL),(0,0,'0d28e85e-665f-74a4-459c-49f88e5aa598','0d28e85e-665f-74a4-459c-49f88e5aa598',20104,39084709973119,20096,NULL,'2026-02-23 13:07:44.508000','2026-02-23 13:07:44.508000',20065,20104,'Power User',NULL,'<?xml version=\"1.0\" ?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">Power Users have their own personal site.</Description></root>',1,NULL),(0,0,'d6325ea9-a6fa-af14-8707-0c6ed8f4f1c0','d6325ea9-a6fa-af14-8707-0c6ed8f4f1c0',20105,39084709973119,20096,NULL,'2026-02-23 13:07:44.517000','2026-02-23 13:07:44.517000',20065,20105,'Publications User',NULL,'<?xml version=\"1.0\" ?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">Publications Users are users who can access the Publications portlet.</Description></root>',1,NULL),(0,0,'73a09e0c-8474-845a-a755-30eb07ff8ba2','73a09e0c-8474-845a-a755-30eb07ff8ba2',20106,39084709973119,20096,NULL,'2026-02-23 13:07:44.543000','2026-02-23 13:07:44.543000',20065,20106,'User',NULL,'<?xml version=\"1.0\" ?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">Authenticated users should be assigned this role.</Description></root>',1,NULL),(0,0,'e16ecf6c-31a7-3a17-852d-f724d60fe049','e16ecf6c-31a7-3a17-852d-f724d60fe049',20107,39084709973119,20096,NULL,'2026-02-23 13:07:44.582000','2026-02-23 13:07:44.582000',20065,20107,'Organization Administrator',NULL,'<?xml version=\"1.0\" ?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">Organization Administrators are super users of their organization but cannot make other users into Organization Administrators.</Description></root>',3,NULL),(0,0,'07735143-2aba-0410-73c0-83beb6bbaa7e','07735143-2aba-0410-73c0-83beb6bbaa7e',20108,39084709973119,20096,NULL,'2026-02-23 13:07:44.591000','2026-02-23 13:07:44.591000',20065,20108,'Organization Owner',NULL,'<?xml version=\"1.0\" ?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">Organization Owners are super users of their organization and can assign organization roles to users.</Description></root>',3,NULL),(0,0,'e3e1c5a0-c8a7-c143-9566-21522b39bbe1','e3e1c5a0-c8a7-c143-9566-21522b39bbe1',20109,39084709973119,20096,NULL,'2026-02-23 13:07:44.601000','2026-02-23 13:07:44.601000',20065,20109,'Organization User',NULL,'<?xml version=\"1.0\" ?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">All users who belong to an organization have this role within that organization.</Description></root>',3,NULL),(0,0,'5092d144-f2ba-3716-8742-87f0523bb31d','5092d144-f2ba-3716-8742-87f0523bb31d',20110,39084709973119,20096,NULL,'2026-02-23 13:07:44.609000','2026-02-23 13:07:44.609000',20065,20110,'Site Administrator',NULL,'<?xml version=\"1.0\" ?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">Site Administrators are super users of their site but cannot make other users into Site Administrators.</Description></root>',2,NULL),(0,0,'272245ca-18c1-d929-0901-e7fb87e9d4a1','272245ca-18c1-d929-0901-e7fb87e9d4a1',20111,39084709973119,20096,NULL,'2026-02-23 13:07:44.616000','2026-02-23 13:07:44.616000',20065,20111,'Site Member',NULL,'<?xml version=\"1.0\" ?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">All users who belong to a site have this role within that site.</Description></root>',2,NULL),(0,0,'0806fed1-ba86-5ad3-dcea-cef02f3c0ab0','0806fed1-ba86-5ad3-dcea-cef02f3c0ab0',20112,39084709973119,20096,NULL,'2026-02-23 13:07:44.625000','2026-02-23 13:07:44.625000',20065,20112,'Site Owner',NULL,'<?xml version=\"1.0\" ?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">Site Owners are super users of their site and can assign site roles to users.</Description></root>',2,NULL),(0,0,'8c83bacd-5257-e7a8-3c02-1c6e318d211b','8c83bacd-5257-e7a8-3c02-1c6e318d211b',20396,39084709973119,20096,NULL,'2026-02-23 13:07:52.997000','2026-02-23 13:07:52.997000',20065,20396,'Asset Library Administrator',NULL,'<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Description language-id=\"sv_SE\">Administratörer av tillgångsbibliotek är superanvändare av sitt tillgångsbibliotek, men kan inte göra andra användare till administratörer i tillgångsbiblioteket.</Description><Description language-id=\"pt_BR\">Os Administradores da Biblioteca de Ativos são super usuários da biblioteca de ativos, mas não podem tornar outros usuários Administradores da Biblioteca de Ativos.</Description><Description language-id=\"ja_JP\">アセットライブラリの管理者はそれぞれのアセットライブラリのスーパーユーザーですが、他のユーザーをアセットライブラリの管理者にすることはできません。</Description><Description language-id=\"fr_FR\">Les administrateurs d\'un dépôt sont des super utilisateurs de leur dépôt, mais ne peuvent rendre administrateurs d\'autres utilisateurs.</Description><Description language-id=\"hu_HU\">Az adattár adminisztrátorai adattáruk magasabbrendű felhasználói, de nem nevezhetnek ki más felhasználókat az adattár adminisztrátoraivá.</Description><Description language-id=\"de_DE\">Repository-Administratoren sind Administratoren ihres Repositorys, können aber andere Benutzer nicht zu Repository-Administratoren machen.</Description><Description language-id=\"ca_ES\">Els administradors de la biblioteca de continguts són superusuaris de la seva biblioteca de continguts, però no poden assignar el rol d\'administrador de biblioteca de continguts a altres usuaris.</Description><Description language-id=\"ar_SA\">مسؤولو مكتبة الأصول هم مستخدمون متميزون لمكتبة الأصول الخاصة بهم ولكن لا يمكنهم تعيين مستخدمين آخرين كمسئولين لمكتبة الأصول.</Description><Description language-id=\"fi_FI\">Sisältökirjaston Pääkäyttäjät ovat sisältökirjastonsa superkäyttäjiä, mutta eivät voi tehdä muista käyttäjistä Sisältökirjaston Pääkäyttäjiä.</Description><Description language-id=\"en_US\">Asset Library Administrators are super users of their asset library but cannot make other users into Asset Library Administrators.</Description><Description language-id=\"zh_CN\">资产库管理员是其资产库的超级用户，但不能使其他用户成为资产库管理员。</Description><Description language-id=\"es_ES\">Los administradores del repositorio son superusuarios de su repositorio, pero no pueden convertir a otros usuarios en administradores del repositorio.</Description><Description language-id=\"nl_NL\">Assetbibliotheekbeheerders zijn supergebruikers van hun assetbibliotheek, maar kunnen geen assetbibliotheekbeheerders maken van andere gebruikers.</Description></root>',5,NULL),(0,0,'cb411aaf-8ad2-3621-27b2-d8f909f13bd0','cb411aaf-8ad2-3621-27b2-d8f909f13bd0',20397,39084709973119,20096,NULL,'2026-02-23 13:07:53.006000','2026-02-23 13:07:53.006000',20065,20397,'Asset Library Connected Site Member',NULL,'',5,NULL),(0,0,'ef8bffa2-aede-f175-2ce7-d59e0f218b26','ef8bffa2-aede-f175-2ce7-d59e0f218b26',20398,39084709973119,20096,NULL,'2026-02-23 13:07:53.014000','2026-02-23 13:07:53.014000',20065,20398,'Asset Library Content Reviewer',NULL,'',5,NULL),(0,0,'08ef5d35-3a5b-ec88-2b28-1040e24ab744','08ef5d35-3a5b-ec88-2b28-1040e24ab744',20399,39084709973119,20096,NULL,'2026-02-23 13:07:53.021000','2026-02-23 13:07:53.021000',20065,20399,'Asset Library Member',NULL,'<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Description language-id=\"sv_SE\">Alla användare som tillhör ett tillgångsbibliotek har den här rollen i det tillgångsbiblioteket.</Description><Description language-id=\"pt_BR\">Todos os usuários que pertencem a uma biblioteca de ativos possuem esta função nessa biblioteca de ativos.</Description><Description language-id=\"ja_JP\">アセットライブラリに属している全ユーザーは、このアセットライブラリでこのロールを割り当てられています。</Description><Description language-id=\"fr_FR\">Tous les utilisateurs qui appartiennent à un dépôt ont ce rôle au sein de ce dépôt.</Description><Description language-id=\"hu_HU\">Egy adattárhoz tartozó összes felhasználó ezzel a szerepkörrel rendelkezik az adattáron belül.</Description><Description language-id=\"de_DE\">Alle Benutzer, die zu einem Repository gehören, haben diese Rolle innerhalb dieses Repositorys inne.</Description><Description language-id=\"ca_ES\">Tots els usuaris que pertanyin a una biblioteca de continguts tenen aquest rol en aquesta biblioteca de continguts.</Description><Description language-id=\"ar_SA\">جميع المستخدمين الذين ينتمون إلى مكتبة أصول ما لديهم هذا الدور داخل مكتبة الأصول تلك.</Description><Description language-id=\"fi_FI\">Kaikilla käyttäjillä, jotka kuuluvat sisältökirjastoon, on tämä rooli kyseisen sisältökirjaston sisällä.</Description><Description language-id=\"en_US\">All users who belong to an asset library have this role within that asset library.</Description><Description language-id=\"zh_CN\">属于资产库的所有用户都具有该资产库中的此角色。</Description><Description language-id=\"es_ES\">Todos los usuarios que pertenecen a un repositorio tienen este rol en ese repositorio.</Description><Description language-id=\"nl_NL\">Alle gebruikers die bij een assetbibliotheek horen, hebben deze rol in die assetbibliotheek.</Description></root>',5,NULL),(0,0,'58b29db4-14c8-5ec8-1b82-fc05e46f1f42','58b29db4-14c8-5ec8-1b82-fc05e46f1f42',20400,39084709973119,20096,NULL,'2026-02-23 13:07:53.030000','2026-02-23 13:07:53.030000',20065,20400,'Asset Library Owner',NULL,'<?xml version=\"1.0\" ?><root available-locales=\"en_US,sv_SE,pt_BR,ja_JP,fr_FR,hu_HU,de_DE,ca_ES,ar_SA,fi_FI,zh_CN,es_ES,nl_NL\" default-locale=\"en_US\"><Description language-id=\"sv_SE\">Administratörer av tillgångsbibliotek är superanvändare av sitt tillgångsbibliotek och kan tilldela roller i tillgångsbiblioteket till användare.</Description><Description language-id=\"pt_BR\">Os Proprietários de Bibliotecas de Ativo são super usuários de suas bibliotecas de ativo e podem atribuir funções da biblioteca de ativos a outros usuários.</Description><Description language-id=\"ja_JP\">アセットライブラリの所有者は、それぞれのアセットライブラリのスーパーユーザーであり、ユーザーにアセットライブラリのロールを割り当てることができます。</Description><Description language-id=\"fr_FR\">Les propriétaires d\'un dépôt sont des super utilisateurs de ce dépôt et peuvent affecter des rôles à des utilisateurs.</Description><Description language-id=\"hu_HU\">Az adattár tulajdonosai adattáruk magasabbrendű felhasználói, és adattár szerepköröket rendelhetnek hozzá más felhasználókhoz.</Description><Description language-id=\"de_DE\">Besitzer von Assetbibliotheken sind Administratoren ihrer Assetbibliothek und können Benutzern Assetbibliothek-Rollen zuweisen.</Description><Description language-id=\"ca_ES\">Els propietaris de la biblioteca de continguts són superusuaris de la seva biblioteca de continguts, i poden assignar rols de la biblioteca de continguts als usuaris.</Description><Description language-id=\"ar_SA\">مالكو مكتبة الأصول هم مستخدمون متميزون لمكتبة الأصول الخاصة بهم ويمكنهم تعيين أدوار مكتبة الأصول إلى المستخدمين.</Description><Description language-id=\"fi_FI\">Sisältökirjaston Omistajat ovat sisältökirjastonsa superkäyttäjiä, ja voivat liittää sisältökirjaston rooleja käyttäjille.</Description><Description language-id=\"en_US\">Asset Library Owners are super users of their asset library and can assign asset library roles to users.</Description><Description language-id=\"zh_CN\">资产库所有者是其资产库的超级用户，且可以将资产库角色分配给用户。</Description><Description language-id=\"es_ES\">Los propietarios de repositorio son superusuarios de su repositorio y pueden asignar roles de repositorio a otros usuarios.</Description><Description language-id=\"nl_NL\">Assetbibliotheekeigenaars zijn supergebruikers van hun assetbibliotheek en kunnen assetbibliotheekrollen toewijzen aan gebruikers.</Description></root>',5,NULL),(1,0,'b090d13d-2430-466e-314a-184cfa32617f','b090d13d-2430-466e-314a-184cfa32617f',29774,39084709973119,20096,NULL,'2026-02-23 13:08:45.279000','2026-02-23 13:08:45.294000',29767,29775,'Account Administrator',NULL,'<?xml version=\"1.0\" ?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">Account Administrators are super users of their account.</Description></root>',6,NULL),(0,0,'c2dc471c-3088-a9f9-311f-45f9cbc416b5','c2dc471c-3088-a9f9-311f-45f9cbc416b5',29776,39084709973119,20096,NULL,'2026-02-23 13:08:45.333000','2026-02-23 13:08:45.333000',20065,29776,'Account Manager',NULL,'<?xml version=\"1.0\" ?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">Account Managers who belong to an organization can administer all accounts associated to that organization.</Description></root>',3,NULL),(1,0,'785485dd-dd77-9d30-5dda-bef55a515367','785485dd-dd77-9d30-5dda-bef55a515367',29777,39084709973119,20096,NULL,'2026-02-23 13:08:45.352000','2026-02-23 13:08:45.360000',29767,29778,'Account Member',NULL,'<?xml version=\"1.0\" ?><root available-locales=\"en_US\" default-locale=\"en_US\"><Description language-id=\"en_US\">All users who belong to an account have this role within that account.</Description></root>',6,NULL),(1,0,'88c6b8ee-3589-ac76-8a68-2ed55e3b460b','88c6b8ee-3589-ac76-8a68-2ed55e3b460b',31342,39084709973119,20123,'Test Test','2026-02-23 13:09:15.128000','2026-02-23 13:09:15.140000',29767,31343,'Buyer','<?xml version=\"1.0\" ?><root available-locales=\"en_US\" default-locale=\"en_US\"><Title language-id=\"en_US\">Buyer</Title></root>','',6,NULL),(1,0,'b778e142-9d42-d82a-3d68-f521131e095b','b778e142-9d42-d82a-3d68-f521131e095b',31344,39084709973119,20123,'Test Test','2026-02-23 13:09:15.178000','2026-02-23 13:09:15.185000',29767,31345,'Order Manager','<?xml version=\"1.0\" ?><root available-locales=\"en_US\" default-locale=\"en_US\"><Title language-id=\"en_US\">Order Manager</Title></root>','',6,NULL),(1,0,'cb49e4e4-2d9a-0989-ff35-dc5828ac209f','cb49e4e4-2d9a-0989-ff35-dc5828ac209f',31346,39084709973119,20123,'Test Test','2026-02-23 13:09:15.198000','2026-02-23 13:09:15.204000',29767,31347,'Account Supplier','<?xml version=\"1.0\" ?><root available-locales=\"en_US\" default-locale=\"en_US\"><Title language-id=\"en_US\">Account Supplier</Title></root>','',6,NULL),(0,0,'c1a757e0-e