  `metadataUpdatedDate` datetime(6) DEFAULT NULL,
  `name` varchar(75) DEFAULT NULL,
  `nameIdAttribute` varchar(1024) DEFAULT NULL,
  `nameIdFormat` varchar(1024) DEFAULT NULL,
  `samlSpEntityId` varchar(1024) DEFAULT NULL,
  PRIMARY KEY (`samlIdpSpConnectionId`),
